import {ControlGroup} from '@github-ui/control-group'

export function PatternConfig({
  patternConfigsLink,
  patternsEnabledCount,
}: {
  patternConfigsLink: string | null
  patternsEnabledCount: number | null
}) {
  if (!patternConfigsLink) return null
  return (
    <ControlGroup.LinkItem
      href={patternConfigsLink}
      value={typeof patternsEnabledCount === 'number' ? `${patternsEnabledCount} patterns enabled` : undefined}
    >
      <ControlGroup.Title className="fgColor-default">Pattern configurations for push protection</ControlGroup.Title>
      <ControlGroup.Description>Select which patterns will be blocked by push protection.</ControlGroup.Description>
    </ControlGroup.LinkItem>
  )
}

try{ PatternConfig.displayName ||= 'PatternConfig' } catch {}